import{_ as l,C as e,o as t,c as s,E as o,a7 as c}from"./chunks/framework.FWlv_suP.js";const g=JSON.parse('{"title":"LocalTell Privacy Policy","description":"Privacy Policy for LocalTell, presented within Policy Hub.","frontmatter":{"title":"LocalTell Privacy Policy","description":"Privacy Policy for LocalTell, presented within Policy Hub."},"headers":[],"relativePath":"apps/local-tell/privacy.md","filePath":"apps/local-tell/privacy.md"}'),d={name:"apps/local-tell/privacy.md"};function p(h,a,u,y,f,v){const i=e("AppBreadcrumbs"),n=e("AppSubnav"),r=e("CopyStandaloneUrl");return t(),s("div",null,[o(i,{"app-id":"local-tell",current:"Privacy Policy"}),o(n,{"app-id":"local-tell"}),o(r,{path:"/privacy/local-tell",label:"Copy Play Store URL","copied-label":"Play Store URL copied","document-name":"LocalTell privacy policy"}),a[0]||(a[0]=c('<h1 id="privacy-policy-for-localtell" tabindex="-1">Privacy Policy for LocalTell <a class="header-anchor" href="#privacy-policy-for-localtell" aria-label="Permalink to &quot;Privacy Policy for LocalTell&quot;">​</a></h1><p><strong>Effective Date:</strong> September 24, 2026<br><strong>Last Updated:</strong> October 4, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>LocalTell is an offline-first Android app developed by <strong>Anand Raja</strong>. It uses an on-device location fix to resolve a locality from an offline geographic data pack installed on your device, and provides cellular diagnostics from information Android reports. It has no account, advertising, analytics, developer-operated tracking, or developer-operated cloud service.</p><h2 id="information-processed-on-your-device" tabindex="-1">Information processed on your device <a class="header-anchor" href="#information-processed-on-your-device" aria-label="Permalink to &quot;Information processed on your device&quot;">​</a></h2><p>After you grant Android&#39;s location permission, LocalTell can read registered serving-cell information supplied by Android: radio technology, mobile country code, mobile network code, area code, cell identifier, and signal strength. It processes this information locally for diagnostics. To resolve a Home locality, LocalTell first requests one short GNSS fix from the Android GPS provider and uses that coordinate only on the device with a downloaded offline SQLite pack.</p><p>If GPS cannot provide a sufficiently usable coordinate, LocalTell may offer an optional <strong>Use assisted location</strong> choice. It requests an assisted current location only after you choose that option, using Android/Google Play services and a usable network connection. The resulting coordinate is still matched only against the offline pack; LocalTell does not perform online reverse geocoding or send the coordinate to the developer.</p><p>The Easy screen requests a location only when you choose <strong>Get my location</strong>. It can locally create and decode LocalTell location codes; these codes represent a coordinate but are not stored in a developer service. Optional Journey mode remains GPS-only: it requests periodic GNSS fixes only while you have explicitly started its foreground service, and stores a local history only when the resolved locality changes.</p><p>If you use Journey mode, LocalTell stores a local history of resolved localities. An entry includes its timestamp, locality, optional district and state, radio technology, network code, cell identifier, and confidence. Offline pack preferences and installed-pack metadata are also kept in app-private storage.</p><h2 id="network-use-and-offline-packs" tabindex="-1">Network use and offline packs <a class="header-anchor" href="#network-use-and-offline-packs" aria-label="Permalink to &quot;Network use and offline packs&quot;">​</a></h2><p>Internet access is used to retrieve the published offline-pack manifest, download a pack you choose, and periodically check for pack updates. It can also be used by Android/Google Play services when you explicitly choose assisted location. Pack URLs use HTTPS and downloaded packs are checked before use. Serving-cell data, Journey history, GNSS coordinates, and locality results are not sent to the developer as part of these requests.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>LocalTell may use the following Android permissions:</p><ul><li>Precise and approximate location permission so Android can provide serving cellular identifiers and, when you request it, a location fix for locality resolution or Easy location sharing. GPS is used first; assisted location is optional and requires your separate choice.</li><li>Internet permission for optional offline-pack downloads and update checks.</li><li>Foreground-service and foreground-service-location permissions for optional Journey mode, which periodically checks the serving cellular network while you have started the service.</li><li>Notification permission on Android versions that require it, only to show the ongoing Journey foreground-service notification.</li></ul><p>You can deny or revoke permissions in Android settings. Without location permission, LocalTell cannot read cell identifiers or resolve a locality. Journey mode requires location access and, where applicable, notification permission.</p><h2 id="sharing-and-external-services" tabindex="-1">Sharing and external services <a class="header-anchor" href="#sharing-and-external-services" aria-label="Permalink to &quot;Sharing and external services&quot;">​</a></h2><p>When you choose Share, Open in Google Maps, Uber, Ola, or Rapido, LocalTell passes the selected location information to the Android app or service you choose. Easy sharing can include the coordinate, LocalTell codes, and a Google Maps link. Ola and Rapido copy the destination before opening their apps. Those external destinations handle the information under their own privacy policies. LocalTell does not automatically share or upload results.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and deletion&quot;">​</a></h2><p>Data remains on your device until you remove it. You can remove an installed offline pack in the Offline data screen and clear Journey history in the Journey screen. Clearing LocalTell&#39;s storage in Android settings or uninstalling LocalTell removes its app-private data, including downloaded packs and Journey history. Android backup and device-transfer rules exclude LocalTell app data.</p><p>The developer does not hold an account or cloud copy of this data, so there is no developer-held app data to delete by email. Support email contains only the information you choose to send.</p><h2 id="children-s-privacy-and-policy-changes" tabindex="-1">Children&#39;s privacy and policy changes <a class="header-anchor" href="#children-s-privacy-and-policy-changes" aria-label="Permalink to &quot;Children&#39;s privacy and policy changes&quot;">​</a></h2><p>LocalTell is not designed to collect children&#39;s personal information through a developer-operated service. This policy may change if the app&#39;s features or data practices change; the dates above will be updated when a revised policy is published.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><ul><li><strong>Developer:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',24))])}const b=l(d,[["render",p]]);export{g as __pageData,b as default};
